{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Hydroxysafflor yellow A, a large polar glycosylated polyphenol with physicochemical properties similar to the query, reached 1026 ng/g in rat brain after systemic administration, directly demonstrating that this compound class can achieve meaningful CNS access despite high polarity and molecular weight.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A glucose-conjugated ketoprofen prodrug was taken up into rat brain by a transporter-mediated mechanism in situ, supporting the possibility that the glucose-containing glycoside query can access the brain via carrier-mediated uptake despite low passive permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Hesperidin, a high-molecular-weight flavonoid glycoside with very high polar surface area, was detected in mouse brain after oral administration, providing direct evidence that glycosylated polyphenols can cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Astragaloside A-VI, a large triterpenoid saponin glycoside, penetrated the blood-brain barrier in healthy rats with a maximal brain concentration of 248.7 ng/g, showing that large glycosides with unfavorable passive properties can still achieve measurable CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Multiple ginsenosides, including large glycosylated saponins, were detected in brain after oral administration despite brain concentrations 8–15 times lower than plasma, indicating meaningful but limited CNS access for this structural class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Although the query has very low passive BBB permeability by physicochemical criteria, multiple high-transfer experimental analogues—large polar glycosides, polyphenolic glycosides, and saponins—show measurable brain concentrations after systemic administration, often via transporter-mediated uptake. The query's glucose/catechol glycoside scaffold aligns with these permeable analogues, so meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct brain concentration or unbound brain-to-plasma ratio is available for the query molecule itself.",
    "The query's specific efflux transporter phenotype (e.g., P-gp or BCRP) has not been directly assayed.",
    "Some analogue brain measurements were obtained after oral prodrug administration or in disease models with possible BBB disruption, which may overestimate normal systemic CNS access.",
    "Several analogue brain/plasma ratios were low, so 'meaningful' access is inferred from detectable ng/g brain concentrations rather than high unbound brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

